const items = $input.all();

return items.map(item => {
  try {
    // Get binary data object
    let binaryData = item.binary?.data;

    if (!binaryData) {
      throw new Error('No binary data found');
    }

    // binaryData is an object, extract the actual data
    let jsonString;

    if (binaryData.data) {
      // It's nested: { data: Buffer, mimeType: '...', fileName: '...' }
      if (Buffer.isBuffer(binaryData.data)) {
        jsonString = binaryData.data.toString('utf8');
      } else if (typeof binaryData.data === 'string') {
        jsonString = Buffer.from(binaryData.data, 'base64').toString('utf8');
      }
    } else if (typeof binaryData === 'string') {
      // Direct string (base64)
      jsonString = Buffer.from(binaryData, 'base64').toString('utf8');
    } else if (Buffer.isBuffer(binaryData)) {
      // Direct buffer
      jsonString = binaryData.toString('utf8');
    } else {
      throw new Error(`Cannot extract data from type: ${typeof binaryData}`);
    }

    // Parse to JSON
    const snapshotData = JSON.parse(jsonString);

    return {
      json: snapshotData
    };
  } catch (error) {
    return {
      json: {
        error: 'Failed to parse file',
        details: error.message
      }
    };
  }
});

